// Service.js
import React, { Component } from "react";
import axios from "axios";
import "./Service.css";

class Service extends Component {
  constructor(props) {
    super(props);
    this.state = {
      servicePage: null,
      showModal: false,
    };
  }

  componentDidMount() {
    fetch("http://localhost:3001/pages/6", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({}),
    })
      .then((response) => response.json())
      .then((page) => this.setState({ servicePage: page }))
      .catch((error) => console.error("Error fetching data:", error));
  }

  fetchData = async () => {
    try {
      const response = await axios.get("http://localhost:3001/trackipetmap");
      const { lat, lng } = response.data;
      console.log(response.data);
      window.location.href = `/map?lat=${lat}&lng=${lng}`;
    } catch (error) {
      console.error(error);
    }
  };

  toggleModal = () => {
    this.setState(prevState => ({ showModal: !prevState.showModal }));
  };

  render() {
    const { servicePage, showModal } = this.state;

    if (!servicePage) return <div>PAGE NOT FOUND</div>;

    const contentService = servicePage.content;

    return (
      <div className="container">
        <div className="image-section"></div>
        <div className="paw"></div>
        <div className="content-section">
          <p className="Hello">{contentService && contentService[0]}</p>
          <p className="Miss">{contentService && contentService[1]}</p>
          <button className="location" onClick={this.fetchData}>
            Pet's Location
          </button>
          <button className="gallery-button" onClick={this.toggleModal}>Find my pet</button>
        </div>

        {showModal && (
          <div className="modal-overlay">
            <div className="modal-content">
              <button onClick={this.toggleModal} className="close-button">X</button>
              {/* תוכן המודאל */}
              <div>
                {/* כאן ניתן להכניס תוכן נוסף או קומפוננטות אחרות */}
                <p>תוכן המודאל</p>
              </div>
            </div>
          </div>
        )}
      </div>
    );
  }
}

export default Service;
